import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Dashboard = ({ token, setToken, setStats }) => {
  const [ledgerData, setLedgerData] = useState({
    folder_name: 'General',
    date: new Date().toISOString().split('T')[0],
    description: '',
    amount: '',
    category: 'expense'
  });
  const [entries, setEntries] = useState([]);
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [uploadFile, setUploadFile] = useState(null);
  const [localStats, setLocalStats] = useState({ total: 0, anomalies: 0, normal: 0 });
  const [pagination, setPagination] = useState({
    page: 1,
    per_page: 10,
    total: 0,
    total_pages: 0
  });
  const [filters, setFilters] = useState({
    startDate: '',
    endDate: '',
    showAnomaliesOnly: false,
    category: 'all',
    folder_name: 'all'
  });
  const [folders, setFolders] = useState([]);

  const fetchEntries = async (page = 1) => {
    if (!token) return;

    try {
      let url = `http://localhost:5000/api/ledger-entries?page=${page}&per_page=${pagination.per_page}`;

      // Add filters to URL
      if (filters.startDate) url += `&start_date=${filters.startDate}`;
      if (filters.endDate) url += `&end_date=${filters.endDate}`;
      if (filters.showAnomaliesOnly) url += `&anomalies_only=true`;
      if (filters.category !== 'all') url += `&category=${filters.category}`;
      if (filters.folder_name !== 'all') url += `&folder_name=${filters.folder_name}`;

      const response = await axios.get(url, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setEntries(response.data.entries);
      setPagination({
        page: response.data.page,
        per_page: response.data.per_page,
        total: response.data.total,
        total_pages: response.data.total_pages
      });

      // Calculate stats from total
      const statsResponse = await axios.get('http://localhost:5000/api/ledger-entries?page=1&per_page=1000', {
        headers: { Authorization: `Bearer ${token}` }
      });
      const allEntries = statsResponse.data.entries;
      const total = allEntries.length;
      const anomalies = allEntries.filter(entry => entry.is_anomaly).length;
      const normal = total - anomalies;
      const statsData = { total, anomalies, normal };
      if (setStats) setStats(statsData);
    } catch (error) {
      console.error('Failed to fetch entries:', error);
    }
  };

  const applyFilters = () => {
    fetchEntries(1);
  };

  const fetchFolders = async () => {
    if (!token) return;
    try {
      const response = await axios.get('http://localhost:5000/api/folders', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setFolders(response.data.folders);
    } catch (error) {
      console.error('Failed to fetch folders:', error);
    }
  };

  const clearFilters = () => {
    setFilters({
      startDate: '',
      endDate: '',
      showAnomaliesOnly: false,
      category: 'all'
    });
    // Auto-refresh will happen due to useEffect
  };

  const exportPDF = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/export-pdf', {
        headers: { Authorization: `Bearer ${token}` },
        responseType: 'blob'
      });

      const url = window.URL.createObjectURL(new Blob([response.data], { type: 'application/pdf' }));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `transaction_report_${new Date().toISOString().split('T')[0]}.pdf`);
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);

      setMessage({
        type: 'success',
        text: 'PDF downloaded successfully!'
      });
    } catch (error) {
      setMessage({
        type: 'error',
        text: error.response?.data?.message || 'PDF export failed'
      });
    }
  };

  const resetAnomalies = async () => {
    if (!window.confirm('This will reset all anomaly flags and retrain the model. Continue?')) {
      return;
    }

    setLoading(true);
    try {
      const response = await axios.post('http://localhost:5000/api/reset-anomalies', {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setMessage({
        type: 'success',
        text: response.data.message
      });
      // Refresh entries after reset
      await fetchEntries();
    } catch (error) {
      setMessage({
        type: 'error',
        text: 'Reset failed. Please try again.'
      });
    } finally {
      setLoading(false);
    }
  };

  const retrainModel = async () => {
    setLoading(true);
    try {
      const response = await axios.post('http://localhost:5000/api/retrain', {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setMessage({
        type: 'success',
        text: response.data.message
      });
    } catch (error) {
      setMessage({
        type: 'error',
        text: 'Model retraining failed'
      });
    } finally {
      setLoading(false);
    }
  };

  // Auto-apply filters when they change
  useEffect(() => {
    if (token) {
      fetchEntries(1);
    }
  }, [filters.startDate, filters.endDate, filters.showAnomaliesOnly, filters.category, filters.folder_name, token]);

  const refreshEntries = async () => {
    try {
      await fetchEntries(pagination.page);
      setMessage({ type: 'success', text: 'Table refreshed successfully!' });
      setTimeout(() => setMessage(''), 3000);
    } catch (error) {
      setMessage({ type: 'error', text: 'Failed to refresh table' });
      setTimeout(() => setMessage(''), 3000);
    }
  };

  // Initial load
  useEffect(() => {
    if (token) {
      fetchEntries();
      fetchFolders();
    }
  }, [token]);

  const handleFileUpload = async (e) => {
    e.preventDefault();
    if (!uploadFile) {
      setMessage({ type: 'error', text: 'Please select a file' });
      return;
    }

    setLoading(true);
    setMessage('');

    const formData = new FormData();
    formData.append('file', uploadFile);

    try {
      const response = await axios({
        method: 'post',
        url: 'http://localhost:5000/api/upload-ledger',
        data: formData,
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'multipart/form-data'
        }
      });

      if (response.data.anomalies_found > 0) {
        setMessage({
          type: 'anomaly',
          text: `File processed! ${response.data.anomalies_found} anomalies detected out of ${response.data.total_entries} entries. Authorities notified.`
        });
      } else {
        setMessage({
          type: 'success',
          text: `File processed successfully! ${response.data.total_entries} entries added, no anomalies detected.`
        });
      }

      setUploadFile(null);
      document.getElementById('fileInput').value = '';

      // Refresh entries
      fetchEntries();
    } catch (error) {
      console.error('Upload error:', error);
      setMessage({
        type: 'error',
        text: error.response?.data?.message || `Upload failed: ${error.message}`
      });
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');

    try {
      const response = await axios.post('http://localhost:5000/api/submit-ledger', ledgerData, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (response.data.anomaly) {
        setMessage({
          type: 'anomaly',
          text: `ANOMALY DETECTED! ${response.data.message} Authority has been notified via email.`
        });
      } else {
        setMessage({
          type: 'success',
          text: response.data.message
        });
      }

      // Reset form
      setLedgerData({
        folder_name: 'General',
        date: new Date().toISOString().split('T')[0],
        description: '',
        amount: '',
        category: 'expense'
      });

      // Refresh entries
      fetchEntries();
    } catch (error) {
      setMessage({
        type: 'error',
        text: error.response?.data?.message || 'Submission failed'
      });
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e) => {
    setLedgerData({
      ...ledgerData,
      [e.target.name]: e.target.value
    });
  };

  const handleLogout = () => {
    setToken(null);
  };

  return (
    <div className="page-content">
      {/* Message Display */}
      {message && (
        <div className={message.type === 'anomaly' ? 'anomaly-alert' : 
                       message.type === 'success' ? 'success-message' : 'error'}>
          {message.text}
        </div>
      )}

      {/* File Upload Card */}
      <div className="card">
        <div className="card-header">
          <h2>📁 Bulk Transaction Upload</h2>
        </div>
        <div className="card-body">
          <form onSubmit={handleFileUpload}>
            <div className="form-group">
              <label>Select CSV or Excel File</label>
              <input
                id="fileInput"
                type="file"
                accept=".csv,.xlsx,.xls"
                onChange={(e) => setUploadFile(e.target.files[0])}
                required
                className="form-input"
              />
            </div>
            <button type="submit" className="btn btn-primary" disabled={loading}>
              {loading ? 'Processing...' : 'Upload & Analyze'}
            </button>
          </form>
          <div className="help-text">
            <strong>Required columns:</strong> date, description, amount, category
          </div>
        </div>
      </div>

      {/* Manual Entry Card */}
      <div className="card">
        <div className="card-header">
          <h2>✏️ Manual Transaction Entry</h2>
        </div>
        <div className="card-body">
          <form onSubmit={handleSubmit}>
            <div className="form-grid">
              <div className="form-group">
                <label>Folder/Project</label>
                <input
                  type="text"
                  name="folder_name"
                  value={ledgerData.folder_name}
                  onChange={handleChange}
                  required
                  placeholder="Enter folder or project name"
                  className="form-input"
                />
              </div>
              <div className="form-group">
                <label>Date</label>
                <input
                  type="date"
                  name="date"
                  value={ledgerData.date}
                  onChange={handleChange}
                  required
                  className="form-input"
                />
              </div>
              <div className="form-group">
                <label>Category</label>
                <select
                  name="category"
                  value={ledgerData.category}
                  onChange={handleChange}
                  required
                  className="form-select"
                >
                  <option value="expense">Expense</option>
                  <option value="income">Income</option>
                  <option value="transfer">Transfer</option>
                  <option value="investment">Investment</option>
                  <option value="loan">Loan</option>
                  <option value="other">Other</option>
                </select>
              </div>
              <div className="form-group">
                <label>Amount (₹)</label>
                <input
                  type="number"
                  step="0.01"
                  name="amount"
                  value={ledgerData.amount}
                  onChange={handleChange}
                  required
                  placeholder="Enter amount in rupees"
                  className="form-input"
                />
              </div>
            </div>
            <div className="form-group">
              <label>Description</label>
              <textarea
                name="description"
                value={ledgerData.description}
                onChange={handleChange}
                required
                placeholder="Enter detailed transaction description..."
                className="form-textarea"
                rows="3"
              />
            </div>
            <button type="submit" className="btn btn-primary" disabled={loading}>
              {loading ? 'Processing...' : 'Submit Transaction'}
            </button>
          </form>
        </div>
      </div>

      {/* Entries Table Card */}
      <div className="card">
        <div className="card-header">
          <h2>📊 Transaction History</h2>
          <div className="card-actions">
            <button onClick={resetAnomalies} className="btn btn-danger" disabled={loading}>
              🔄 Reset & Retrain Model
            </button>
            <button onClick={exportPDF} className="btn btn-secondary">
              📄 Export PDF
            </button>
          </div>
        </div>

        <div className="card-body">
          {/* Filter Controls */}
          <div className="filter-section">
            <div className="filter-grid">
              <div className="filter-item">
                <label>From Date:</label>
                <input
                  type="date"
                  value={filters.startDate}
                  onChange={(e) => setFilters({...filters, startDate: e.target.value})}
                  className="form-input"
                />
              </div>
              <div className="filter-item">
                <label>To Date:</label>
                <input
                  type="date"
                  value={filters.endDate}
                  onChange={(e) => setFilters({...filters, endDate: e.target.value})}
                  className="form-input"
                />
              </div>
              <div className="filter-item">
                <label>Folder/Project:</label>
                <select
                  value={filters.folder_name}
                  onChange={(e) => setFilters({...filters, folder_name: e.target.value})}
                  className="form-select"
                >
                  <option value="all">All Folders</option>
                  {folders.map(folder => (
                    <option key={folder} value={folder}>📁 {folder}</option>
                  ))}
                </select>
              </div>
              <div className="filter-item">
                <label>Category:</label>
                <select
                  value={filters.category}
                  onChange={(e) => setFilters({...filters, category: e.target.value})}
                  className="form-select"
                >
                  <option value="all">All Categories</option>
                  <option value="expense">💸 Expense</option>
                  <option value="income">💰 Income</option>
                  <option value="transfer">🔄 Transfer</option>
                  <option value="investment">📈 Investment</option>
                  <option value="loan">🏦 Loan</option>
                  <option value="other">📋 Other</option>
                </select>
              </div>
              <div className="filter-item">
                <label className="checkbox-label">
                  <input
                    type="checkbox"
                    checked={filters.showAnomaliesOnly}
                    onChange={(e) => setFilters({...filters, showAnomaliesOnly: e.target.checked})}
                  />
                  Show Anomalies Only
                </label>
              </div>
              <div className="filter-item">
                <button onClick={refreshEntries} className="btn btn-outline">
                  🔄 Refresh Table
                </button>
                <button onClick={clearFilters} className="btn btn-outline">
                  🗑️ Clear Filters
                </button>
              </div>
            </div>
          </div>
        {entries.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '3rem', color: '#718096' }}>
            <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>📊</div>
            <p>No entries found. Start by adding your first transaction!</p>
          </div>
        ) : (
          <>
            <div className="table-container">
              <table className="entries-table">
                <thead>
                  <tr>
                    <th style={{width: '120px'}}>Folder</th>
                    <th style={{width: '100px'}}>Date</th>
                    <th style={{minWidth: '200px'}}>Description</th>
                    <th style={{width: '120px'}}>Amount</th>
                    <th style={{width: '100px'}}>Category</th>
                    <th style={{width: '80px'}}>Status</th>
                    <th style={{width: '140px'}}>Created</th>
                  </tr>
                </thead>
                <tbody>
                  {entries.map((entry) => (
                    <tr key={entry.id}>
                      <td>📁 {entry.folder_name}</td>
                      <td>{entry.date}</td>
                      <td>{entry.description}</td>
                      <td>₹{parseFloat(entry.amount).toLocaleString('en-IN', {minimumFractionDigits: 2})}</td>
                      <td style={{ textTransform: 'capitalize' }}>{entry.category}</td>
                      <td>
                        {entry.is_anomaly ? (
                          <span className="anomaly-badge">ANOMALY</span>
                        ) : (
                          <span className="normal-badge">NORMAL</span>
                        )}
                      </td>
                      <td>{new Date(entry.created_at).toLocaleString('en-IN', {
                        year: 'numeric',
                        month: '2-digit',
                        day: '2-digit',
                        hour: '2-digit',
                        minute: '2-digit',
                        hour12: true
                      })}</td>
                    </tr>
                  ))}}
                </tbody>
              </table>
            </div>

            {/* Pagination */}
            <div className="pagination">
              <div className="pagination-info">
                Showing {((pagination.page - 1) * pagination.per_page) + 1} to {Math.min(pagination.page * pagination.per_page, pagination.total)} of {pagination.total} entries
              </div>
              <div className="pagination-controls">
                <button 
                  onClick={() => fetchEntries(pagination.page - 1)}
                  disabled={pagination.page <= 1}
                  className="pagination-btn"
                >
                  Previous
                </button>
                <span className="page-info">
                  Page {pagination.page} of {pagination.total_pages}
                </span>
                <button 
                  onClick={() => fetchEntries(pagination.page + 1)}
                  disabled={pagination.page >= pagination.total_pages}
                  className="pagination-btn"
                >
                  Next
                </button>
              </div>
            </div>
          </>
        )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
